// qs.mjs — tiny query-string library
//
// parse(search)  : query string (with or without leading '?', or a full URL)
//                  -> plain object.
//   - repeated keys become arrays                       a=1&a=2     -> {a:[1,2]}
//   - bracketed keys become nested objects              a[b][c]=d   -> {a:{b:{c:'d'}}}
//   - a[] pushes onto an array                          e[]=1&e[]=2 -> {e:[1,2]}
//   - keys with no '=' sign map to null                 a&b=1       -> {a:null,b:1}
//   - '+' is decoded as space; UTF-8 percent-escapes are decoded;
//     invalid escapes are left as-is instead of throwing.
//
// stringify(obj) : plain object/array -> query string, such that
//                  parse(stringify(x)) deep-equals x for supported shapes
//                  (objects, arrays of scalars, strings/numbers/booleans/null).
//   - null/undefined values emit a bare key (no '='), which parses back as null
//   - nested objects are encoded with literal brackets; keys that merely
//     *contain* brackets have them percent-encoded so round-trips are stable
//
// Known trade-offs (inherent to the format): empty arrays/objects are skipped,
// and string values that look like canonical numbers or "true"/"false" are
// coerced on parse.

const KEY_RE = /^([^[\]]*)((?:\[[^[\]]*\])*)$/;
const BRACKET_RE = /\[([^[\]]*)\]/g;

function decodePart(part) {
  const spaced = part.replace(/\+/g, ' ');
  try {
    return decodeURIComponent(spaced);
  } catch {
    return spaced; // malformed escape: keep raw text rather than throwing
  }
}

function coerce(value) {
  if (value === 'true') return true;
  if (value === 'false') return false;
  if (value !== '') {
    const num = Number(value);
    if (Number.isFinite(num) && String(num) === value) return num;
  }
  return value;
}

function assign(root, path, value) {
  let node = root;
  for (let i = 0; i < path.length - 1; i++) {
    const key = path[i];
    if (!Object.hasOwn(node, key) || node[key] === null || typeof node[key] !== 'object') {
      node[key] = {};
    }
    node = node[key];
  }
  const last = path[path.length - 1];
  if (last === '') { // e.g. "a[]" — append to array
    if (Array.isArray(node)) node.push(value);
    return;
  }
  if (Object.hasOwn(node, last)) {
    const current = node[last];
    if (Array.isArray(current)) current.push(value);
    else if (current !== null && typeof current === 'object') return; // shape conflict: ignore
    else node[last] = [current, value]; // repeated key -> array
  } else {
    node[last] = value;
  }
}

export function parse(search) {
  const result = {};
  if (typeof search !== 'string') return result;

  let qs = search;
  const qIndex = qs.indexOf('?');
  if (qIndex !== -1) qs = qs.slice(qIndex + 1); // tolerate full URLs
  qs = qs.split('#')[0]; // drop fragment
  if (qs === '') return result;

  for (const pair of qs.split('&')) {
    if (pair === '') continue;
    const eq = pair.indexOf('=');
    const rawKey = eq === -1 ? pair : pair.slice(0, eq);
    const hasValue = eq !== -1;
    const rawValue = hasValue ? pair.slice(eq + 1) : '';

    // Split into path segments on *raw* text, before decoding, so that an
    // encoded key like "a%5Bb%5D" stays a single flat key ("a[b]") while a
    // literal "a[b]" becomes nested. This is what makes round-trips stable.
    const match = KEY_RE.exec(rawKey);
    let segments;
    if (match && match[2]) {
      segments = [match[1]];
      for (const seg of match[2].matchAll(BRACKET_RE)) segments.push(seg[1]);
    } else {
      segments = [rawKey];
    }

    const path = segments.map(decodePart);
    const value = hasValue ? coerce(decodePart(rawValue)) : null;
    assign(result, path, value);
  }
  return result;
}

const encKey = (s) => encodeURIComponent(String(s));
const encValue = (s) => encKey(s).replace(/%20/g, '+');

export function stringify(obj) {
  if (obj === null || obj === undefined) return '';
  if (typeof obj !== 'object' || Array.isArray(obj)) {
    throw new TypeError('stringify expects a plain object at the root');
  }

  const parts = [];
  const keyOf = (path) =>
    encKey(path[0]) +
    path
      .slice(1)
      .map((seg) => `[${encKey(seg)}]`)
      .join('');

  const walk = (value, path) => {
    if (value === null || value === undefined) {
      parts.push(keyOf(path)); // bare key, parses back as null
    } else if (typeof value !== 'object') {
      parts.push(`${keyOf(path)}=${encValue(value)}`);
    } else if (Array.isArray(value)) {
      for (const item of value) walk(item, path); // repeated keys
    } else if (Object.keys(value).length > 0) {
      for (const k of Object.keys(value)) walk(value[k], [...path, k]);
    } // empty containers: not representable in a query string, skipped
  };

  for (const k of Object.keys(obj)) walk(obj[k], [k]);
  return parts.join('&');
}

