import test from 'node:test';
import assert from 'node:assert/strict';
import { parse, stringify } from './qs.mjs';

test('basic parse with numeric coercion', () => {
  assert.deepEqual(parse('a=1&b=two'), { a: 1, b: 'two' });
});

test('parse tolerates leading "?" and full URLs, drops fragment', () => {
  assert.deepEqual(parse('?x=1'), { x: 1 });
  assert.deepEqual(parse('https://example.com/p?x=1#frag'), { x: 1 });
});

test('plus-as-space and literal plus via %2B', () => {
  assert.deepEqual(parse('a+b=c+d'), { 'a b': 'c d' });
  assert.deepEqual(parse('a%2Bb=c%2Dd'), { 'a+b': 'c-d' });
});

test('UTF-8 percent-encoding incl. emoji values', () => {
  assert.deepEqual(parse('%E2%9C%93=%F0%9F%98%8A'), { '✓': '😊' });
  assert.deepEqual(parse('caf%C3%A9=na%C3%AFve'), { café: 'naïve' });
});

test('repeated keys become arrays', () => {
  assert.deepEqual(parse('tag=x&tag=y&tag=z'), { tag: ['x', 'y', 'z'] });
});

test('key with no "=" maps to null', () => {
  assert.deepEqual(parse('flag&b=1'), { flag: null, b: 1 });
});

test('bracketed nested keys', () => {
  assert.deepEqual(parse('a[b][c]=deep&e[]=1&e[]=2'), {
    a: { b: { c: 'deep' } },
    e: [1, 2],
  });
});

test('malformed percent escapes do not throw', () => {
  assert.deepEqual(parse('%zz=ok&ok=%E0%A4%A'), { '%zz': 'ok', ok: '%E0%A4%A' });
});

test('stringify basics: bare key for null, repeated keys for arrays', () => {
  assert.equal(stringify({ a: 1, b: null }), 'a=1&b');
  assert.equal(stringify({ tags: ['x', 'y'] }), 'tags=x&tags=y');
  assert.equal(stringify({ nested: { deep: true } }), 'nested[deep]=true');
});

test('stringify percent-encodes values and + as space', () => {
  assert.equal(stringify({ q: 'hello world & friends=😊' }), 'q=hello+world+%26+friends%3D%F0%9F%98%8A');
});

test('keys needing encoding round-trip (spaces, &, =, emoji, unicode)', () => {
  const obj = {
    'a key': 'v',
    'a&b': 'c=d',
    'café ☕': 'naïve 😌',
    '😀': '🎉',
  };
  assert.deepEqual(parse(stringify(obj)), obj);
});

test('keys containing literal brackets stay flat across round-trip', () => {
  const obj = { 'a[b]': 'flat', real: { nested: 5 } };
  const encoded = stringify(obj);
  assert.equal(encoded.includes('%5Bb%5D'), true);
  assert.deepEqual(parse(encoded), obj);
});

test('round-trip: mixed supported shapes deep-equal', () => {
  const obj = {
    str: 'plain',
    num: -3.5,
    bool: false,
    nul: null,
    list: ['one', 2, true, null],
    user: { name: 'Ada', langs: ['js', 'py'], meta: { active: true } },
  };
  assert.deepEqual(parse(stringify(obj)), obj);
});

test('empty string / empty object edge cases', () => {
  assert.deepEqual(parse(''), {});
  assert.deepEqual(parse('&a=1&&'), { a: 1 });
  assert.equal(stringify({}), '');
  assert.throws(() => stringify([1, 2]), TypeError);
});

